// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {DEP_BANK} from "../src/DEP_BANK.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    DEP_BANK c;
    bool public initializedOnce;

    function setUp() public {
        c = new DEP_BANK();
    }

    function _test(uint256 min1, uint256 min2) internal {
        vm.assume(min1 != min2);
        try c.SetLogFile(address(0)) {} catch { return; }
        try c.SetMinSum(min1) {} catch { return; }
        try c.Initialized() {} catch { return; }
        try c.SetMinSum(min2) {} catch { return; }
        uint sumsEqual = (c.MinSum() == min1) ? 1 : 0;
        assertTrue(sumsEqual == 1);
    }

    function testFuzz_test(uint256 min1, uint256 min2) public {
        _test(min1, min2);
    }

    receive() external payable {}
}
